% Model-mismatch validation for HFT identifiability study.
%
% Data-generating model:
%   non-symmetric two-port network + frequency-dependent Rac(f)
%   + different Cg1/Cg2 and Gg1/Gg2.
%
% Identification model:
%   reduced symmetric 4-parameter model [Lsigma, Cps, Cg, Rac],
%   fixed Gg, constant Rac.
%
% Purpose:
%   Check whether the simplified model can still recover useful effective
%   parameters when the "true" response is generated by a richer model.

clear; clc; close all;
rng(20260708);

scriptDir = fileparts(mfilename('fullpath'));
projectDir = fileparts(scriptDir);
dataDir = fullfile(projectDir, char([25968 25454]));
if ~exist(dataDir, 'dir')
    mkdir(dataDir);
end

channels = {'Y11','Y12','Y22'};
paramNames = {'Lsigma','Cps','Cg','Rac'};

% Candidate frequency grid.
nCandidate = 260;
fCand = logspace(3, 7, nCandidate);
wCand = 2*pi*fCand;

% Rich "truth" model parameters. These values are intentionally close to
% the earlier nominal model, but include asymmetry and frequency dependence.
truth.Ls1 = 1.7e-6;
truth.Ls2 = 2.4e-6;
truth.Rdc1 = 0.08;
truth.Rdc2 = 0.11;
truth.kac1 = 0.055;     % Rac1(f) = Rdc1 + kac1*sqrt(f/1MHz)
truth.kac2 = 0.075;
truth.C12 = 85e-12;
truth.Cg1 = 95e-12;
truth.Cg2 = 150e-12;
truth.Gg1 = 0.6e-6;
truth.Gg2 = 1.4e-6;
truth.G12 = 0.15e-6;

% Reduced identification model nominal values.
thetaNom = [2.0e-6, 80e-12, 120e-12, 0.20];
GgFixed = 1.0e-6;

% Best PWM condition from previous experiments.
pwm.tr = 50e-9;
pwm.fs = 500e3;
pwm.duty = 0.3;
U2 = pwm_spectrum_weight(fCand, pwm.fs, pwm.duty, pwm.tr);
baseRelNoise = 0.006;
noiseFloor = 0.03;
relSigma = min(baseRelNoise ./ sqrt(noiseFloor + U2), 0.12);

% Frequency selection based on the reduced model. This is realistic: design
% is done with the simplified model, then tested on a richer truth model.
contribNominal = fim_contributions_reduced(wCand, thetaNom, GgFixed, channels, relSigma);
idxEopt = sort(greedy_eopt_select(contribNominal, 40));
idxUniform = unique(round(linspace(1, nCandidate, 40)));
idxUniform = pad_to_k(idxUniform, nCandidate, 40);

strategies(1).name = "full_260_mismatch";
strategies(1).idx = 1:nCandidate;
strategies(2).name = "eopt_40_mismatch";
strategies(2).idx = idxEopt;
strategies(3).name = "uniform_40_mismatch";
strategies(3).idx = idxUniform;

nTrials = 40;
Tmc = run_mismatch_mc(fCand, truth, thetaNom, GgFixed, channels, relSigma, strategies, nTrials, paramNames);
writetable(Tmc, fullfile(dataDir, 'model_mismatch_mc_summary.csv'));

% Also compare true rich-model response and best reduced-model fit without noise.
[thetaFitFull, fitCost] = estimate_theta(wCand, select_channels(rich_twoport_y(wCand, truth), channels), ...
    relSigma(:).' .* max(abs(select_channels(rich_twoport_y(wCand, truth), channels)), 1e-12), ...
    thetaNom, GgFixed, channels);
Hrich = select_channels(rich_twoport_y(wCand, truth), channels);
Hfit = select_channels(reduced_twoport_y(wCand, thetaFitFull, GgFixed), channels);
relFitErr = abs(Hfit - Hrich) ./ max(abs(Hrich), 1e-12);

save(fullfile(dataDir, 'model_mismatch_validation.mat'), ...
    'Tmc', 'truth', 'thetaNom', 'thetaFitFull', 'fitCost', ...
    'fCand', 'idxEopt', 'idxUniform', 'Hrich', 'Hfit', 'relFitErr');

plot_mismatch_results(fCand, Tmc, idxEopt, idxUniform, Hrich, Hfit, relFitErr, dataDir);
write_report(Tmc, truth, thetaNom, thetaFitFull, fitCost, dataDir);
disp(Tmc);

function idx = pad_to_k(idx, nCandidate, K)
    if numel(idx) >= K
        idx = idx(1:K);
        return;
    end
    extra = setdiff(1:nCandidate, idx, 'stable');
    idx = sort([idx(:); extra(1:(K-numel(idx))).']);
end

function Tmc = run_mismatch_mc(fCand, truth, thetaNom, GgFixed, channels, relSigma, strategies, nTrials, paramNames)
    rows = [];
    wCand = 2*pi*fCand;
    for iStrat = 1:numel(strategies)
        idx = strategies(iStrat).idx;
        w = wCand(idx);
        sigmaRel = relSigma(idx);
        Htrue = select_channels(rich_twoport_y(w, truth), channels);
        measStd = sigmaRel(:).' .* max(abs(Htrue), 1e-12);
        thetaHat = nan(nTrials, numel(thetaNom));
        fitRelErr = nan(nTrials, 1);

        for t = 1:nTrials
            noise = (randn(size(Htrue)) + 1i*randn(size(Htrue))) ./ sqrt(2) .* measStd;
            Hmeas = Htrue + noise;
            thetaHat(t,:) = estimate_theta(w, Hmeas, measStd, thetaNom, GgFixed, channels);
            Hhat = select_channels(reduced_twoport_y(w, thetaHat(t,:), GgFixed), channels);
            fitRelErr(t) = mean(abs(Hhat(:)-Htrue(:)) ./ max(abs(Htrue(:)), 1e-12));
        end

        relErrToNom = (thetaHat - thetaNom) ./ thetaNom;
        rows(iStrat).strategy = string(strategies(iStrat).name); %#ok<AGROW>
        rows(iStrat).K = numel(idx);
        rows(iStrat).meanFitRelErrPct = 100 * mean(fitRelErr);
        rows(iStrat).stdFitRelErrPct = 100 * std(fitRelErr);
        for p = 1:numel(paramNames)
            rows(iStrat).(['meanEff_', paramNames{p}]) = mean(thetaHat(:,p));
            rows(iStrat).(['stdPct_', paramNames{p}]) = 100 * std(relErrToNom(:,p));
            rows(iStrat).(['shiftPct_', paramNames{p}]) = 100 * mean(relErrToNom(:,p));
        end
    end
    Tmc = struct2table(rows);
    Tmc = sortrows(Tmc, 'meanFitRelErrPct', 'ascend');
end

function [thetaBest, bestCost] = estimate_theta(w, Hmeas, measStd, thetaNom, GgFixed, channels)
    logNom = log(thetaNom);
    starts = [
         0,     0,     0,     0
         0.10, -0.10,  0.08,  0.08
        -0.12,  0.10, -0.08, -0.08
         0.25,  0.18, -0.16,  0.12
        -0.25, -0.18,  0.16, -0.12
    ];
    bestCost = inf;
    thetaBest = thetaNom;
    opts = optimset('Display','off', 'MaxIter', 900, 'MaxFunEvals', 3500, ...
        'TolX', 1e-8, 'TolFun', 1e-8);
    for i = 1:size(starts,1)
        x0 = logNom + starts(i,:);
        obj = @(x) objective(x, w, Hmeas, measStd, thetaNom, GgFixed, channels);
        [x, cost] = fminsearch(obj, x0, opts);
        if cost < bestCost
            bestCost = cost;
            thetaBest = exp(x);
        end
    end
end

function cost = objective(logTheta, w, Hmeas, measStd, thetaPrior, GgFixed, channels)
    theta = exp(logTheta);
    Hhat = select_channels(reduced_twoport_y(w, theta, GgFixed), channels);
    r = [(real(Hhat-Hmeas) ./ measStd), (imag(Hhat-Hmeas) ./ measStd)];
    cost = sum(huber_loss(r(:), 1.5));
    cost = cost + 0.01 * sum(((logTheta - log(thetaPrior)) ./ 0.9).^2);
end

function rho = huber_loss(r, delta)
    a = abs(r);
    rho = 0.5 * r.^2;
    idx = a > delta;
    rho(idx) = delta * (a(idx) - 0.5*delta);
end

function Y = rich_twoport_y(w, truth)
    f = w(:).'/(2*pi);
    s = 1i*w(:).';
    Rac1 = truth.Rdc1 + truth.kac1 * sqrt(f/1e6);
    Rac2 = truth.Rdc2 + truth.kac2 * sqrt(f/1e6);
    ys1 = 1 ./ (Rac1 + s*truth.Ls1);
    ys2 = 1 ./ (Rac2 + s*truth.Ls2);
    y12c = truth.G12 + s*truth.C12;
    yg1 = truth.Gg1 + s*truth.Cg1;
    yg2 = truth.Gg2 + s*truth.Cg2;

    % A compact asymmetric pi-like network. The series branch is represented
    % by an averaged leakage path plus inter-winding capacitive coupling.
    ys = 2 ./ (1./ys1 + 1./ys2);
    Y11 = yg1 + y12c + ys;
    Y22 = yg2 + y12c + ys;
    Y12 = -y12c - ys;

    Y = zeros(2,2,numel(w));
    Y(1,1,:) = Y11;
    Y(2,2,:) = Y22;
    Y(1,2,:) = Y12;
    Y(2,1,:) = Y12;
end

function Y = reduced_twoport_y(w, theta, GgFixed)
    Lsigma = theta(1);
    Cps = theta(2);
    Cg = theta(3);
    Rac = theta(4);
    s = 1i*w(:).';
    ys = 1 ./ (Rac + s*Lsigma);
    yps = s*Cps;
    yg = GgFixed + s*Cg;
    Y11 = yg + yps + ys;
    Y22 = yg + yps + ys;
    Y12 = -yps - ys;

    Y = zeros(2,2,numel(w));
    Y(1,1,:) = Y11;
    Y(2,2,:) = Y22;
    Y(1,2,:) = Y12;
    Y(2,1,:) = Y12;
end

function H = select_channels(Y, channels)
    nFreq = size(Y,3);
    H = zeros(numel(channels), nFreq);
    for k = 1:numel(channels)
        switch channels{k}
            case 'Y11'
                H(k,:) = reshape(Y(1,1,:), 1, nFreq);
            case 'Y12'
                H(k,:) = reshape(Y(1,2,:), 1, nFreq);
            case 'Y22'
                H(k,:) = reshape(Y(2,2,:), 1, nFreq);
        end
    end
end

function contrib = fim_contributions_reduced(w, theta, GgFixed, channels, relSigma)
    nFreq = numel(w);
    nParam = numel(theta);
    contrib = zeros(nParam, nParam, nFreq);
    for k = 1:nFreq
        S = reduced_sensitivity(w(k), theta, GgFixed, channels);
        H = select_channels(reduced_twoport_y(w(k), theta, GgFixed), channels);
        sigma = relSigma(k) * max(abs(H(:)), 1e-12);
        W = repmat(1 ./ sigma(:).^2, 1, nParam);
        contrib(:,:,k) = real(S' * (S .* W));
    end
end

function S = reduced_sensitivity(w, theta, GgFixed, channels)
    nParam = numel(theta);
    H0 = select_channels(reduced_twoport_y(w, theta, GgFixed), channels); %#ok<NASGU>
    S = zeros(numel(H0), nParam);
    step = 1e-4;
    for p = 1:nParam
        tp = theta; tm = theta;
        tp(p) = theta(p) * exp(step);
        tm(p) = theta(p) * exp(-step);
        Hp = select_channels(reduced_twoport_y(w, tp, GgFixed), channels);
        Hm = select_channels(reduced_twoport_y(w, tm, GgFixed), channels);
        S(:,p) = reshape((Hp-Hm)/(2*step), [], 1);
    end
end

function selected = greedy_eopt_select(contrib, K)
    nFreq = size(contrib, 3);
    selected = zeros(1, K);
    current = 1e-18 * eye(size(contrib,1));
    available = true(1, nFreq);
    for k = 1:K
        bestScore = -inf;
        bestIdx = 1;
        for i = find(available)
            score = min(eig(current + contrib(:,:,i)));
            if score > bestScore
                bestScore = score;
                bestIdx = i;
            end
        end
        selected(k) = bestIdx;
        current = current + contrib(:,:,bestIdx);
        available(bestIdx) = false;
    end
end

function U2 = pwm_spectrum_weight(f, fs, duty, tr)
    x = f / fs;
    dutyEnvelope = abs(sin(pi*duty*x) ./ max(pi*x, 1e-12));
    riseEnvelope = abs(sinc_local(f*tr));
    U2 = (dutyEnvelope .* riseEnvelope).^2;
    U2 = U2(:).' / max(U2(:));
end

function y = sinc_local(x)
    y = ones(size(x));
    nz = abs(x) > 1e-12;
    y(nz) = sin(pi*x(nz)) ./ (pi*x(nz));
end

function plot_mismatch_results(f, Tmc, idxEopt, idxUniform, Hrich, Hfit, relFitErr, dataDir)
    figure('Color','w','Position',[100,100,980,420]);
    bar(1:height(Tmc), Tmc.meanFitRelErrPct);
    set(gca, 'XTick', 1:height(Tmc), 'XTickLabel', cellstr(Tmc.strategy));
    xtickangle(20);
    ylabel('Mean response fit error (%)');
    title('Model-mismatch validation: rich truth, reduced identification model');
    grid on;
    saveas(gcf, fullfile(dataDir, 'model_mismatch_fit_error_bar.png'));

    figure('Color','w','Position',[100,100,980,420]);
    semilogx(f(idxUniform), ones(size(idxUniform)), 'o'); hold on;
    semilogx(f(idxEopt), 1.08*ones(size(idxEopt)), 'x');
    ylim([0.94, 1.14]);
    set(gca, 'YTick', [1,1.08], 'YTickLabel', {'uniform','eopt'});
    grid on;
    xlabel('Frequency (Hz)');
    title('Frequency points used in mismatch validation');
    saveas(gcf, fullfile(dataDir, 'model_mismatch_selected_points.png'));

    figure('Color','w','Position',[100,100,1000,640]);
    chNames = {'Y11','Y12','Y22'};
    for k = 1:3
        subplot(3,1,k);
        loglog(f, abs(Hrich(k,:)), 'k-', 'LineWidth', 1.4); hold on;
        loglog(f, abs(Hfit(k,:)), 'r--', 'LineWidth', 1.1);
        grid on;
        ylabel(['|', chNames{k}, '|']);
        if k == 1
            title('Rich-model response versus best reduced-model fit');
            legend('Rich truth','Reduced fit','Location','best');
        end
        if k == 3
            xlabel('Frequency (Hz)');
        end
    end
    saveas(gcf, fullfile(dataDir, 'model_mismatch_response_fit.png'));

    figure('Color','w','Position',[100,100,980,420]);
    loglog(f, mean(relFitErr,1), 'LineWidth', 1.4);
    grid on;
    xlabel('Frequency (Hz)');
    ylabel('Mean relative response error');
    title('Best reduced-model fit error against rich truth');
    saveas(gcf, fullfile(dataDir, 'model_mismatch_response_error.png'));
end

function write_report(Tmc, truth, thetaNom, thetaFit, fitCost, dataDir)
    reportPath = fullfile(dataDir, 'model_mismatch_validation_report.md');
    fid = fopen(reportPath, 'w');
    fprintf(fid, '# 模型失配验证实验\n\n');
    fprintf(fid, '生成时间：%s\n\n', datestr(now, 'yyyy-mm-dd HH:MM:SS'));
    fprintf(fid, '## 目的\n\n');
    fprintf(fid, '用更复杂的非对称两端口模型生成频响，再用四参数简化模型反演，检验前面方法是否只对同模型合成数据有效。\n\n');
    fprintf(fid, '## 复杂真值模型\n\n');
    fprintf(fid, '- Ls1 = %.3e H\n', truth.Ls1);
    fprintf(fid, '- Ls2 = %.3e H\n', truth.Ls2);
    fprintf(fid, '- C12 = %.3e F\n', truth.C12);
    fprintf(fid, '- Cg1 = %.3e F\n', truth.Cg1);
    fprintf(fid, '- Cg2 = %.3e F\n', truth.Cg2);
    fprintf(fid, '- Rac1(f) = %.3f + %.3f sqrt(f/1MHz) Ohm\n', truth.Rdc1, truth.kac1);
    fprintf(fid, '- Rac2(f) = %.3f + %.3f sqrt(f/1MHz) Ohm\n\n', truth.Rdc2, truth.kac2);
    fprintf(fid, '## 简化辨识模型\n\n');
    fprintf(fid, '`theta = [Lsigma, Cps, Cg, Rac]`, fixed Gg = 1e-6 S.\n\n');
    fprintf(fid, '标称值：Lsigma=%.3e H, Cps=%.3e F, Cg=%.3e F, Rac=%.3e Ohm.\n\n', thetaNom);
    fprintf(fid, '无噪声全频最佳等效参数：Lsigma=%.3e H, Cps=%.3e F, Cg=%.3e F, Rac=%.3e Ohm, cost=%.3e.\n\n', thetaFit, fitCost);
    fprintf(fid, '## Monte Carlo 结果\n\n');
    fprintf(fid, '| strategy | K | meanFitRelErrPct | stdFitRelErrPct |\n');
    fprintf(fid, '|---|---:|---:|---:|\n');
    for i = 1:height(Tmc)
        fprintf(fid, '| %s | %d | %.4g | %.4g |\n', Tmc.strategy(i), Tmc.K(i), Tmc.meanFitRelErrPct(i), Tmc.stdFitRelErrPct(i));
    end
    fprintf(fid, '\n## 解释\n\n');
    fprintf(fid, '如果简化模型在复杂真值模型下仍能保持较小响应拟合误差，说明它可作为核心频段的有效等效模型；如果误差明显增大，则说明必须升级辨识模型或缩窄适用频段。\n');
    fclose(fid);
end
